160	     * Derived from the owner's own fields, so it stays consistent with them.
161	     */
162	    @Transient
163	    public String getMembershipTier() {
164	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
165	        boolean hasEmail = this.email != null && !this.email.isEmpty();
166	        return unique && hasEmail ? "SILVER" : "BRONZE";
167	    }
168	
169	    /**
170	     * The owner's locality: the canonical region derived from the city via the fixed
171	     * {@link CityRegionTable}, or {@code "UNKNOWN"} when the city is not in the table.
172	     * Derived from the owner's own city, so it stays consistent with it.
173	     */
174	    @Transient
175	    public String getLocality() {
176	        return CityRegionTable.regionFor(this.city);
177	    }
178	
179	    /**
180	     * Normalize the registration date before persisting: default it to the server's
181	     * current date when none was supplied, then roll it forward onto a business day so
182	     * every newly persisted owner is registered on a weekday.
183	     */
184	    @PrePersist
185	    void normalizeRegistrationDate() {
186	        if (this.registrationDate == null) {
187	            this.registrationDate = LocalDate.now();
188	        }
189	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
190	    }
191	
192	    protected Set<Pet> getPetsInternal() {
193	        if (this.pets == null) {
194	            this.pets = new HashSet<>();
195	        }
196	        return this.pets;
197	    }
198	
199	    protected void setPetsInternal(Set<Pet> pets) {
200	        this.pets = pets;
201	    }
202	
203	    public List<Pet> getPets() {
204	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
205	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
206	        return Collections.unmodifiableList(sortedPets);
207	    }
208	
209	    public void setPets(List<Pet> pets) {
210	        this.pets = new HashSet<>(pets);
211	    }
212	
213	    public void addPet(Pet pet) {
214	        getPetsInternal().add(pet);
215	        pet.setOwner(this);
216	    }
217	
218	    /**
219	     * Return the Pet with the given name, or null if none found for this Owner.
220	     *
221	     * @param name to test
222	     * @return true if pet name is already in use
223	     */
224	    public Pet getPet(String name) {
225	        return getPet(name, false);
226	    }
227	
228	    /**
229	     * Return the Pet with the given name, or null if none found for this Owner.
230	     *
231	     * @param name to test
232	     * @return true if pet name is already in use
233	     */
234	    public Pet getPet(String name, boolean ignoreNew) {
235	        name = name.toLowerCase();
236	        for (Pet pet : getPetsInternal()) {
237	            if (!ignoreNew || !pet.isNew()) {
238	                String compName = pet.getName();
239	                compName = compName.toLowerCase();
240	                if (compName.equals(name)) {
241	                    return pet;
242	                }
243	            }
244	        }
245	        return null;
246	    }
247	
248	    public Pet getPet(Integer petId) {
249	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
250	    }
251	
252	    @Override
253	    public String toString() {
254	        return new ToStringCreator(this)
255	
256	            .append("id", this.getId())
257	            .append("new", this.isNew())
258	            .append("lastName", this.getLastName())
259	            .append("firstName", this.getFirstName())
260	            .append("address", this.address)
261	            .append("city", this.city)
262	            .append("telephone", this.telephone)
263	            .toString();
264	    }
265	}
