36	 * Also a placeholder for @Transactional and @Cacheable annotations
37	 *
38	 * @author Michael Isvy
39	 * @author Vitaliy Fedoriv
40	 */
41	@Service
42	public class ClinicServiceImpl implements ClinicService {
43	
44	    /**
45	     * Number of owners that must already carry a day's registration date before a
46	     * further owner registered that day is flagged with a bulk signup warning.
47	     */
48	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
49	
50	    private final PetRepository petRepository;
51	    private final VetRepository vetRepository;
52	    private final OwnerRepository ownerRepository;
53	    private final VisitRepository visitRepository;
54	    private final SpecialtyRepository specialtyRepository;
55	    private final PetTypeRepository petTypeRepository;
56	    private final CustomerCodeGenerator customerCodeGenerator;
57	    private final HouseholdIdGenerator householdIdGenerator;
58	
59	    public ClinicServiceImpl(
60	        PetRepository petRepository,
61	        VetRepository vetRepository,
62	        OwnerRepository ownerRepository,
63	        VisitRepository visitRepository,
64	        SpecialtyRepository specialtyRepository,
65	        PetTypeRepository petTypeRepository,
66	        CustomerCodeGenerator customerCodeGenerator,
67	        HouseholdIdGenerator householdIdGenerator) {
68	        this.petRepository = petRepository;
69	        this.vetRepository = vetRepository;
70	        this.ownerRepository = ownerRepository;
71	        this.visitRepository = visitRepository;
72	        this.specialtyRepository = specialtyRepository;
73	        this.petTypeRepository = petTypeRepository;
74	        this.customerCodeGenerator = customerCodeGenerator;
75	        this.householdIdGenerator = householdIdGenerator;
76	    }
77	
78	    @Override
79	    @Transactional(readOnly = true)
80	    public Collection<Pet> findAllPets() throws DataAccessException {
81	        return petRepository.findAll();
82	    }
83	
84	    @Override
85	    @Transactional(readOnly = true)
86	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
87	        return petRepository.findAll(pageable);
88	    }
89	
90	    @Override
91	    @Transactional
92	    public void deletePet(Pet pet) throws DataAccessException {
93	        petRepository.delete(pet);
94	    }
95	
96	    @Override
97	    @Transactional(readOnly = true)
98	    public Visit findVisitById(int visitId) throws DataAccessException {
99	        return findEntityById(() -> visitRepository.findById(visitId));
100	    }
101	
102	    @Override
103	    @Transactional(readOnly = true)
104	    public Collection<Visit> findAllVisits() throws DataAccessException {
105	        return visitRepository.findAll();
106	    }
107	
108	    @Override
109	    @Transactional
110	    public void deleteVisit(Visit visit) throws DataAccessException {
111	        visitRepository.delete(visit);
112	    }
113	
114	    @Override
115	    @Transactional(readOnly = true)
116	    public Vet findVetById(int id) throws DataAccessException {
117	        return findEntityById(() -> vetRepository.findById(id));
118	    }
119	
120	    @Override
121	    @Transactional(readOnly = true)
122	    public Collection<Vet> findAllVets() throws DataAccessException {
123	        return vetRepository.findAll();
124	    }
125	
126	    @Override
127	    @Transactional
128	    public void saveVet(Vet vet) throws DataAccessException {
129	        vetRepository.save(vet);
130	    }
131	
132	    @Override
133	    @Transactional
134	    public void deleteVet(Vet vet) throws DataAccessException {
135	        vetRepository.delete(vet);
136	    }
137	
138	    @Override
139	    @Transactional(readOnly = true)
140	    public Collection<Owner> findAllOwners() throws DataAccessException {
141	        return ownerRepository.findAll();
142	    }
143	
144	    @Override
145	    @Transactional(readOnly = true)
146	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
147	        if (lastName != null) {
148	            return ownerRepository.findByLastName(lastName, pageable);
149	        }
150	        return ownerRepository.findAll(pageable);
151	    }
152	
153	    @Override
154	    @Transactional
155	    public void deleteOwner(Owner owner) throws DataAccessException {
156	        ownerRepository.delete(owner);
157	    }
158	
159	    @Override
160	    @Transactional(readOnly = true)
161	    public PetType findPetTypeById(int petTypeId) {
162	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
163	    }
164	
165	    @Override
166	    @Transactional(readOnly = true)
167	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
168	        return petTypeRepository.findAll();
169	    }
170	
171	    @Override
172	    @Transactional
173	    public void savePetType(PetType petType) throws DataAccessException {
174	        petTypeRepository.save(petType);
175	    }
176	
177	    @Override
178	    @Transactional
179	    public void deletePetType(PetType petType) throws DataAccessException {
180	        petTypeRepository.delete(petType);
181	    }
182	
183	    @Override
184	    @Transactional(readOnly = true)
185	    public Specialty findSpecialtyById(int specialtyId) {
186	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
187	    }
188	
189	    @Override
190	    @Transactional(readOnly = true)
191	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
192	        return specialtyRepository.findAll();
193	    }
194	
195	    @Override
196	    @Transactional
197	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
198	        specialtyRepository.save(specialty);
199	    }
