207	    @Override
208	    @Transactional(readOnly = true)
209	    public Collection<PetType> findPetTypes() throws DataAccessException {
210	        return petRepository.findPetTypes();
211	    }
212	
213	    @Override
214	    @Transactional(readOnly = true)
215	    public Owner findOwnerById(int id) throws DataAccessException {
216	        return findEntityById(() -> ownerRepository.findById(id));
217	    }
