225	    @Override
226	    @Transactional
227	    public void savePet(Pet pet) throws DataAccessException {
228	        pet.setType(findPetTypeById(pet.getType().getId()));
229	        petRepository.save(pet);
230	    }
231	
232	    @Override
233	    @Transactional
234	    public void saveVisit(Visit visit) throws DataAccessException {
235	        visitRepository.save(visit);
236	
237	    }
238	
239	    @Override
240	    @Transactional(readOnly = true)
241	    public Collection<Vet> findVets() throws DataAccessException {
242	        return vetRepository.findAll();
243	    }
244	
245	    @Override
246	    @Transactional
247	    public void saveOwner(Owner owner) throws DataAccessException {
248	        if (owner.isNew()) {
249	            if (owner.getCustomerCode() == null) {
250	                owner.setCustomerCode(customerCodeGenerator.generate(
251	                    owner.getCity(), owner.getLastName(), ownerRepository.countByCity(owner.getCity())));
252	            }
253	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
254	            owner.setBulkSignupWarning(
255	                ownerRepository.countByRegistrationDate(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
256	        }
257	        ownerRepository.save(owner);
258	
259	    }
260	
261	    /**
262	     * Count the existing owners that already share the given first and last name,
263	     * compared case-insensitively. Used to stamp a new owner's namesake count at
264	     * registration, before it is itself persisted.
265	     */
266	    private int countNamesakes(String firstName, String lastName) {
267	        return (int) ownerRepository.findByLastNameIgnoreCase(lastName).stream()
268	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName))
269	            .count();
270	    }
271	
272	    @Override
273	    @Transactional(readOnly = true)
274	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
275	        return ownerRepository.findByLastName(lastName);
276	    }
277	
278	    @Override
279	    @Transactional(readOnly = true)
280	    public boolean existsOwnerByTelephone(String telephone) throws DataAccessException {
281	        return ownerRepository.existsByTelephone(telephone);
282	    }
283	
284	    @Override
285	    @Transactional(readOnly = true)
286	    public boolean existsOwnerByLastNameAndAddress(String lastName, String address) throws DataAccessException {
287	        return !householdMembers(lastName, address).isEmpty();
288	    }
289	
290	    @Override
291	    @Transactional(readOnly = true)
292	    public long countOwnersByCity(String city) throws DataAccessException {
293	        return ownerRepository.countByCity(city);
294	    }
295	
296	    @Override
297	    @Transactional(readOnly = true)
298	    public long countOwnersByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
299	        return ownerRepository.countByRegistrationDate(registrationDate);
300	    }
301	
302	    @Override
303	    @Transactional
304	    public String shareHousehold(Owner owner) throws DataAccessException {
305	        String householdId = householdIdGenerator.generate(owner.getLastName(), owner.getAddress());
306	        // Backfill the existing members so the whole household carries one shared id.
307	        householdMembers(owner.getLastName(), owner.getAddress()).stream()
308	            .filter(member -> !householdId.equals(member.getHouseholdId()))
309	            .forEach(member -> {
310	                member.setHouseholdId(householdId);
311	                ownerRepository.save(member);
312	            });
313	        owner.setHouseholdId(householdId);
314	        return householdId;
315	    }
316	
317	    /**
318	     * Return the existing owners that already occupy the household identified by the
319	     * given last name and address, i.e. that map to the same shared household id.
320	     */
321	    private List<Owner> householdMembers(String lastName, String address) {
322	        String householdId = householdIdGenerator.generate(lastName, address);
323	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
324	            .filter(owner -> householdId.equals(
325	                householdIdGenerator.generate(owner.getLastName(), owner.getAddress())))
326	            .toList();
327	    }
328	
329	    @Override
330	    @Transactional(readOnly = true)
331	    public Collection<Visit> findVisitsByPetId(int petId) {
332	        return visitRepository.findByPetId(petId);
333	    }
334	
335	    @Override
336	    @Transactional(readOnly = true)
337	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
338	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
339	    }
340	
341	    private <T> T findEntityById(Supplier<T> supplier) {
342	        try {
343	            return supplier.get();
344	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
345	            // Just ignore not found exceptions for Jdbc/Jpa realization
346	            return null;
347	        }
348	    }
349	
350	}
