package org.springframework.samples.petclinic.repository.jpa;

import java.time.LocalDate;
import java.util.Collection;
import java.util.List;

import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import jakarta.persistence.Query;

import org.jspecify.annotations.NonNull;
import org.springframework.context.annotation.Profile;
import org.springframework.dao.DataAccessException;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageImpl;
import org.springframework.data.domain.Pageable;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.stereotype.Repository;

/**
 * JPA implementation of the {@link OwnerRepository} interface.
 *
 * @author Mike Keith
 * @author Rod Johnson
 * @author Sam Brannen
 * @author Michael Isvy
 * @author Vitaliy Fedoriv
 */
@Repository
@Profile("jpa")
public class JpaOwnerRepositoryImpl implements OwnerRepository {

    @PersistenceContext
    private EntityManager em;


    /**
     * Important: in the current version of this method, we load Owners with all their Pets and Visits while
     * we do not need Visits at all and we only need one property from the Pet objects (the 'name' property).
     * There are some ways to improve it such as:
     * - creating a Ligtweight class (example here: https://community.jboss.org/wiki/LightweightClass)
     * - Turning on lazy-loading and using open session in view pattern
     */
    @SuppressWarnings("unchecked")
    public Collection<Owner> findByLastName(String lastName) {
        // using 'join fetch' because a single query should load both owners and pets
        // using 'left join fetch' because it might happen that an owner does not have pets yet
        Query query = this.em.createQuery("SELECT DISTINCT owner FROM Owner owner left join fetch owner.pets WHERE owner.lastName LIKE :lastName");
        query.setParameter("lastName", lastName + "%");
        return query.getResultList();
    }

    @Override
    @SuppressWarnings("unchecked")
    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE owner.lastName LIKE :lastName ORDER BY owner.id");
        query.setParameter("lastName", lastName + "%");
        query.setFirstResult((int) pageable.getOffset());
        query.setMaxResults(pageable.getPageSize());
        List<Owner> owners = query.getResultList();
        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE owner.lastName LIKE :lastName");
        countQuery.setParameter("lastName", lastName + "%");
        long total = (long) countQuery.getSingleResult();
        return new PageImpl<>(owners, pageable, total);
    }

    @Override
    public Owner findById(int id) {
        // using 'join fetch' because a single query should load both owners and pets
        // using 'left join fetch' because it might happen that an owner does not have pets yet
        Query query = this.em.createQuery("SELECT owner FROM Owner owner left join fetch owner.pets WHERE owner.id =:id");
        query.setParameter("id", id);
        return (Owner) query.getSingleResult();
    }


    @Override
    public boolean existsByTelephone(String telephone) throws DataAccessException {
        Query query = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE owner.telephone = :telephone");
        query.setParameter("telephone", telephone);
        return (long) query.getSingleResult() > 0;
    }

    @Override
    @SuppressWarnings("unchecked")
    public Collection<Owner> findByLastNameIgnoreCase(String lastName) throws DataAccessException {
        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE LOWER(owner.lastName) = LOWER(:lastName)");
        query.setParameter("lastName", lastName);
        return query.getResultList();
    }

    @Override
    public void save(Owner owner) {
        if (owner.getId() == null) {
            this.em.persist(owner);
        } else {
            this.em.merge(owner);
        }

    }

	@SuppressWarnings("unchecked")
	@Override
	public Collection<Owner> findAll() throws DataAccessException {
		Query query = this.em.createQuery("SELECT owner FROM Owner owner");
        return query.getResultList();
	}

    @SuppressWarnings("unchecked")
    @Override
    public Page<Owner> findAll(@NonNull Pageable pageable) throws DataAccessException {
        Query query = this.em.createQuery("SELECT owner FROM Owner owner ORDER BY owner.id");
        query.setFirstResult((int) pageable.getOffset());
        query.setMaxResults(pageable.getPageSize());
        List<Owner> owners = query.getResultList();
        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner");
        long total = (long) countQuery.getSingleResult();
        return new PageImpl<>(owners, pageable, total);
    }

	@Override
	public void delete(Owner owner) throws DataAccessException {
		this.em.remove(this.em.contains(owner) ? owner : this.em.merge(owner));
	}

    @Override
    public long count() throws DataAccessException {
        Query query = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner");
        return (long) query.getSingleResult();
    }

    @Override
    public long countByCity(String city) throws DataAccessException {
        Query query = this.em.createQuery(
            "SELECT COUNT(owner) FROM Owner owner WHERE LOWER(owner.city) = LOWER(:city)");
        query.setParameter("city", city);
        return (long) query.getSingleResult();
    }

    @Override
    public long countByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
        Query query = this.em.createQuery(
            "SELECT COUNT(owner) FROM Owner owner WHERE owner.registrationDate = :registrationDate");
        query.setParameter("registrationDate", registrationDate);
        return (long) query.getSingleResult();
    }

}

